package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonResponse;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Take the person's statement: record their due-total now (late charges included, at most the sheet's cap) and the sheet's today, bind
 *  each of their claims that counts to the figure under it now (never its late charge, which keeps following the
 *  sheet's today), and unbind the rest (their due is live again). A settled claim's
 *  fixed due is left as it is. */
public class SaveStatement {
    public void save(@Val Person loaded, PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings, Out<Statement> statement, Out<PersonResponse> saved) {
        people.lock(loaded);
        Person person = people.find(loaded.sheetId(), loaded.id());
        var today = sheets.today(person.sheetId());
        var floor = settings.floor(person.sheetId());
        List<Claim> theirs = claims.listForPerson(person.sheetId(), person.id());
        LateCharge late = LateCharge.of(person.sheetId(), settings, sheets, claims);
        BigDecimal total = Dues.capped(Dues.total(person.sheetId(), theirs, person.grades(), person.holds(), today,
                rates, floor, late), settings.cap(person.sheetId()));
        int counted = 0;
        for (Claim c : theirs) {
            if (Dues.counts(c, person.holds())) {
                counted++;
                claims.state(c, true, Dues.figure(c, person.grades(), rates, floor, late.rounding()));
            } else if (c.stated()) {
                claims.state(c, false, null);
            }
        }
        people.stated(person, total, today);
        statement.set(new Statement(person.sheetId(), person.name(), total, counted));
        saved.set(PersonResponse.from(people.find(person.sheetId(), person.id())));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Move the loaded claim to its new status, refusing a change its status does not allow (or one
 *  another user's change got to first). Opening gives the claim the sheet's next number; voiding
 *  keeps it (a number is never reused). Opening records who opened it, and that user may not settle it. Settling fixes its due
 *  as its row shows it now: the bound figure, else live at the person's grade rate now in force on the claim's date,
 *  at least the sheet's floor, with the late charge as of today frozen in. When a clerk (any user not made a steward)
 *  settles a claim whose due (as shown: bound by a statement, else live, plus any late charge) is above the sheet's
 *  clerk limit, it becomes PENDING instead (a due of n/a, or no limit, is within it). A steward other than the
 *  user who opened it approves a PENDING claim (it becomes SETTLED, its due as its row shows it then — live, a
 *  PENDING claim is not bound by a statement — frozen in) or rejects it (OPEN again, bound again by the statement
