import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Store the new claim under the person; with no date given it is dated the sheet's today. Its due-by is fixed now:
 *  its date plus the terms of the person's grade in force on its date (else the sheet's terms in force on its date). Its DRAFT line starts its status log. */
public class SaveNewClaim {
    public void save(@Val ClaimInput input, @Val Person person, SheetRepository sheets, SettingRepository settings,
            ClaimRepository repository, ClaimLogRepository log, Out<Claim> claim) {
        claim.set(insert(input, person, sheets, settings, repository, log));
    }

    /** Store one new claim as the claim form does (the paste box stores each of its lines this way). */
    static Claim insert(ClaimInput input, Person person, SheetRepository sheets, SettingRepository settings,
            ClaimRepository repository, ClaimLogRepository log) {
        var date = input.date() != null ? input.date() : sheets.today(person.sheetId());
        var dueBy = date.plusDays(settings.termsFor(person.sheetId(), person.grades().on(date), date));
        Claim added = repository.insert(new Claim(0, person.sheetId(), person.id(), input.amount(), date, input.note(),
                ClaimStatus.DRAFT, null, null, null, false, null, input.corrects(), dueBy));
        log.record(added, input.user());
        return added;
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Sheets by id. A sheet is created the first time its id is loaded, and starts empty. */
@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public boolean exists(String id) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, id);
        return n != null && n > 0;
    }

    /**
     * Create the sheet unless it already exists (concurrent first loads are harmless). A new sheet's
     * today starts as the real date — the only place the app reads the real clock.
     */
    public void ensure(String id, String user) {
        jdbc.update("MERGE INTO sheet s USING (VALUES (CAST(? AS VARCHAR(100)), CAST(? AS VARCHAR(100)), CAST(? AS DATE))) "
                + "v(id, created_by, today) ON s.id = v.id "
                + "WHEN NOT MATCHED THEN INSERT (id, created_by, today) VALUES (v.id, v.created_by, v.today)",
                id, user, LocalDate.now());
    }

    /** The sheet's today: the date every date-dependent decision on the sheet uses. Null when absent. */
    public LocalDate today(String id) {
        return jdbc.query("SELECT today FROM sheet WHERE id = ?",
                rs -> rs.next() ? rs.getObject(1, LocalDate.class) : null, id);
    }

    public void setToday(String id, LocalDate today) {
        jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", today, id);
    }
}
